typedef struct GradeBook GradeBook;

typedef enum {
    GRADEBOOK_OK = 0,
    GRADEBOOK_INVALID_ARGUMENT,
    GRADEBOOK_NO_MEMORY,
    GRADEBOOK_EMPTY
} GradeBookStatus;

GradeBook *gradebook_create(void);
void gradebook_destroy(GradeBook *book);
GradeBookStatus gradebook_add(GradeBook *book, int score);
size_t gradebook_count(const GradeBook *book);
GradeBookStatus gradebook_average(const GradeBook *book, double *average);
