cat > src/gradebook.c <<'EOF'
#include "gradebook.h"

#include <stdint.h>
#include <stdlib.h>

struct GradeBook {
    int *scores;
    size_t count;
    size_t capacity;
};

static int reserve_scores(GradeBook *book, size_t needed)
{
    size_t capacity;
    int *temporary;

    if (needed <= book->capacity) {
        return 1;
    }
    if (needed > SIZE_MAX / sizeof *book->scores) {
        return 0;
    }

    capacity = book->capacity == 0U ? 4U : book->capacity;
    while (capacity < needed) {
        if (capacity > SIZE_MAX / 2U) {
            capacity = needed;
            break;
        }
        capacity *= 2U;
    }
    if (capacity > SIZE_MAX / sizeof *book->scores) {
        return 0;
    }

    temporary = realloc(book->scores, capacity * sizeof *book->scores);
    if (temporary == NULL) {
        return 0;
    }
    book->scores = temporary;
    book->capacity = capacity;
    return 1;
}

GradeBook *gradebook_create(void)
{
    return calloc(1U, sizeof(GradeBook));
}

void gradebook_destroy(GradeBook *book)
{
    if (book != NULL) {
        free(book->scores);
        book->scores = NULL;
        free(book);
    }
}

GradeBookStatus gradebook_add(GradeBook *book, int score)
{
    if (book == NULL || score < 0 || score > 100) {
        return GRADEBOOK_INVALID_ARGUMENT;
    }
    if (book->count == SIZE_MAX ||
        !reserve_scores(book, book->count + 1U)) {
        return GRADEBOOK_NO_MEMORY;
    }
    book->scores[book->count] = score;
    ++book->count;
    return GRADEBOOK_OK;
}

size_t gradebook_count(const GradeBook *book)
{
    return book == NULL ? 0U : book->count;
}

GradeBookStatus gradebook_average(const GradeBook *book, double *average)
{
    size_t i;
    long double total = 0.0L;

    if (book == NULL || average == NULL) {
        return GRADEBOOK_INVALID_ARGUMENT;
    }
    if (book->count == 0U) {
        return GRADEBOOK_EMPTY;
    }
    for (i = 0U; i < book->count; ++i) {
        total += (long double)book->scores[i];
    }
    *average = (double)(total / (long double)book->count);
    return GRADEBOOK_OK;
}

GradeBookStatus gradebook_min_max(
    const GradeBook *book, int *minimum, int *maximum)
{
    size_t i;
    int low;
    int high;

    if (book == NULL || minimum == NULL || maximum == NULL) {
        return GRADEBOOK_INVALID_ARGUMENT;
    }
    if (book->count == 0U) {
        return GRADEBOOK_EMPTY;
    }

    low = book->scores[0];
    high = book->scores[0];
    for (i = 1U; i < book->count; ++i) {
        if (book->scores[i] < low) {
            low = book->scores[i];
        }
        if (book->scores[i] > high) {
            high = book->scores[i];
        }
    }
    *minimum = low;
    *maximum = high;
    return GRADEBOOK_OK;
}
EOF

cat > src/main.c <<'EOF'
#include "gradebook.h"

#include <stdio.h>

int main(void)
{
    const int sample_scores[] = {82, 91, 76, 100, 88};
    const size_t sample_count =
        sizeof sample_scores / sizeof sample_scores[0];
    GradeBook *book = gradebook_create();
    size_t i;
    double average;
    int minimum;
    int maximum;

    if (book == NULL) {
        fputs("Could not create grade book.\n", stderr);
        return 1;
    }

    for (i = 0U; i < sample_count; ++i) {
        if (gradebook_add(book, sample_scores[i]) != GRADEBOOK_OK) {
            fputs("Could not add score.\n", stderr);
            gradebook_destroy(book);
            return 1;
        }
    }

    if (gradebook_average(book, &average) != GRADEBOOK_OK ||
        gradebook_min_max(book, &minimum, &maximum) != GRADEBOOK_OK) {
        fputs("Could not calculate grade summary.\n", stderr);
        gradebook_destroy(book);
        return 1;
    }

    printf("Students: %zu\n", gradebook_count(book));
    printf("Average: %.2f\n", average);
    printf("Lowest: %d\n", minimum);
    printf("Highest: %d\n", maximum);

    gradebook_destroy(book);
    return 0;
}
EOF

