	$(CC) $(CPPFLAGS) $(CFLAGS) tests/test_gradebook.c $(LIB_SOURCE) -o $@

test: $(BUILD)/test_gradebook
	./$(BUILD)/test_gradebook

clean:
	rm -rf $(BUILD)
EOF

