#!/bin/sh
set -eu

# Run this after Example 1 has created include/gradebook.h and src/gradebook.c.
mkdir -p tests build

cat > tests/test_gradebook.c <<'EOF'
#include "gradebook.h"

#include <assert.h>
#include <stdio.h>

int main(void)
{
    GradeBook *book = gradebook_create();
    double average = 0.0;
    int minimum = -1;
    int maximum = -1;

    assert(book != NULL);
    assert(gradebook_count(book) == 0U);
    assert(gradebook_average(book, &average) == GRADEBOOK_EMPTY);
    assert(gradebook_min_max(book, &minimum, &maximum) == GRADEBOOK_EMPTY);
    assert(gradebook_add(book, 75) == GRADEBOOK_OK);
    assert(gradebook_add(book, 100) == GRADEBOOK_OK);
    assert(gradebook_add(book, 0) == GRADEBOOK_OK);
    assert(gradebook_add(book, 101) == GRADEBOOK_INVALID_ARGUMENT);
    assert(gradebook_add(book, -1) == GRADEBOOK_INVALID_ARGUMENT);
    assert(gradebook_count(book) == 3U);
    assert(gradebook_average(book, &average) == GRADEBOOK_OK);
    assert(average > 58.333 && average < 58.334);
    assert(gradebook_min_max(book, &minimum, &maximum) == GRADEBOOK_OK);
    assert(minimum == 0);
    assert(maximum == 100);
    assert(gradebook_average(NULL, &average) == GRADEBOOK_INVALID_ARGUMENT);
    gradebook_destroy(book);
    gradebook_destroy(NULL);

    puts("GradeBook API tests passed.");
    return 0;
}
EOF

make test
